// FIX: Added fallback for exam_code lookup in case node reference breaks.
const result = $input.first().json;
let exam;
try {
  exam = $('Process One Exam at a Time').first().json.exam_code;
} catch (e) {
  exam = 'UNKNOWN';
}
const examResult = (result.results && result.results[exam]) || {};
return [{
  json: {
    exam_code: exam,
    status: examResult.status || 'unknown',
    chunks_indexed: examResult.chunks_indexed || 0,
    files: examResult.files || 0,
    reason: examResult.reason || null
  }
}];
